"""Writes LinuxKPI Manager's application icon (an HVIF vector_icon) into
src/apps/linuxkpimanager/LinuxKPIManagerIcon.rdef:

    3rdparty/ce/tools/make_linuxkpi_manager_icon.py > \\
        src/apps/linuxkpimanager/LinuxKPIManagerIcon.rdef
    3rdparty/ce/tools/make_linuxkpi_manager_icon.py --preview icon.png

The picture: an expansion card (the hardware a Linux driver runs) seen in
Haiku's three-quarter view, with its chip and gold contacts, and an orange
gear in front (managing it). Haiku's icon style: lit from the top left,
gradients, dark outlines; colours from the Renga leaf palette (green,
orange, gold; 3rdparty/ce/artwork/make_splash_renga.py).
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hvif

# the Renga leaf palette: (light, dark)
GREEN = ((126, 190, 74, 255), (78, 140, 46, 255))
ORANGE = ((240, 128, 40, 255), (196, 84, 22, 255))
GOLD = ((246, 196, 64, 255), (206, 150, 30, 255))

GREEN_OUTLINE = (34, 70, 20, 255)
ORANGE_OUTLINE = (110, 44, 8, 255)
CHIP_OUTLINE = (16, 18, 22, 255)


def offset(points, dx, dy):
	return [(x + dx, y + dy) for x, y in points]


def lerp(a, b, t):
	return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)


def build():
	icon = hvif.Icon()

	# the card: a board lying in three-quarter view, 4 units thick
	a, b, c, d = (3, 33), (35, 17), (61, 30), (29, 46)
	depth = 4
	board = [a, b, c, d]
	icon.polygon([a, d, offset([d], 0, depth)[0], offset([a], 0, depth)[0]],
		hvif.gradient((3, 33), (29, 50), [(0, GREEN[1]),
			(255, (52, 100, 30, 255))]), outline=(GREEN_OUTLINE, 3))
	icon.polygon([d, c, offset([c], 0, depth)[0], offset([d], 0, depth)[0]],
		hvif.gradient((29, 46), (61, 34), [(0, (60, 112, 34, 255)),
			(255, (44, 88, 26, 255))]), outline=(GREEN_OUTLINE, 3))
	icon.polygon(board, hvif.gradient((14, 20), (44, 46),
		[(0, GREEN[0]), (255, GREEN[1])]), outline=(GREEN_OUTLINE, 3))

	# gold contacts along the front edge's side
	for i in range(7):
		t0 = 0.12 + i * 0.11
		p0 = lerp(d, c, t0)
		p1 = lerp(d, c, t0 + 0.06)
		icon.polygon([(p0[0], p0[1] + 0.8), (p1[0], p1[1] + 0.8),
			(p1[0], p1[1] + depth - 0.6), (p0[0], p0[1] + depth - 0.6)],
			hvif.gradient((0, 44), (0, 50), [(0, GOLD[0]), (255, GOLD[1])]))

	# traces: light lines on the board
	for start, end in (((10, 34), (24, 27)), ((22, 40), (36, 33)),
			((40, 24), (50, 29))):
		dx, dy = 0.5, 1.0
		icon.polygon([start, end, (end[0] + dx, end[1] + dy),
			(start[0] + dx, start[1] + dy)], (170, 220, 120, 200))

	# the chip: a dark block standing 3 units on the board
	ca, cb, cc, cd = (20, 29), (32, 23), (44, 29), (32, 35)
	lift = 3
	icon.polygon([offset([ca], 0, -lift)[0], offset([cd], 0, -lift)[0], cd,
		ca], (40, 43, 48, 255), outline=(CHIP_OUTLINE, 2))
	icon.polygon([offset([cd], 0, -lift)[0], offset([cc], 0, -lift)[0], cc,
		cd], (28, 30, 34, 255), outline=(CHIP_OUTLINE, 2))
	icon.polygon(offset([ca, cb, cc, cd], 0, -lift), hvif.gradient((24, 22),
		(40, 34), [(0, (96, 102, 112, 255)), (255, (52, 56, 62, 255))]),
		outline=(CHIP_OUTLINE, 2))
	# a dot marking pin 1
	icon.polygon(hvif.circle(25.5, 27.5 - lift + 1, 1.2, 8),
		(180, 186, 196, 255))

	# the gear, in front at the top right
	cx, cy = 47, 15
	teeth = 8
	points = []
	for i in range(teeth):
		base = i * 360.0 / teeth
		for angle, radius in ((base - 13, 10.5), (base - 8, 13.5),
				(base + 8, 13.5), (base + 13, 10.5)):
			points += hvif.arc_points(cx, cy, radius, angle, angle, 1)[:1]
	icon.polygon(points, hvif.gradient((38, 5), (56, 25),
		[(0, ORANGE[0]), (255, ORANGE[1])]), outline=(ORANGE_OUTLINE, 3))
	icon.polygon(hvif.circle(cx, cy, 4.5, 16), hvif.gradient((43, 11),
		(51, 19), [(0, (120, 50, 12, 255)), (255, GOLD[0])]),
		outline=(ORANGE_OUTLINE, 2))
	return icon


def rdef():
	data = build().flat()
	hexdata = data.hex().upper()
	lines = ["/*", " * Copyright 2026, Renga contributors.",
		" * Distributed under the terms of the MIT License.", " *",
		" * LinuxKPI Manager's icon. Generated by",
		" * 3rdparty/ce/tools/make_linuxkpi_manager_icon.py; see there.",
		" */", "", "resource vector_icon {"]
	for i in range(0, len(hexdata), 64):
		lines.append("\t$\"%s\"" % hexdata[i:i + 64])
	lines.append("};")
	return "\n".join(lines) + "\n"


if __name__ == "__main__":
	if len(sys.argv) == 3 and sys.argv[1] == "--preview":
		from PIL import Image
		icon = build()
		sheet = Image.new("RGBA", (16 + 32 + 64 + 128 + 40, 140),
			(216, 216, 216, 255))
		x = 8
		for size in (16, 32, 64, 128):
			sheet.paste(icon.preview(size, (216, 216, 216, 255)), (x, 4))
			x += size + 8
		sheet.save(sys.argv[2])
	else:
		print(rdef(), end="")
